namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    CrossEntropyLossCustomTilingData tiling;

    auto inShape = context->GetInputShape(0);
    uint32_t rows = 1;
    uint32_t cols = 1;
    if (inShape != nullptr) {
        auto storage = inShape->GetStorageShape();
        if (storage.GetDimNum() >= 2) {
            rows = static_cast<uint32_t>(storage.GetDim(0));
            cols = static_cast<uint32_t>(storage.GetDim(1));
        } else if (storage.GetDimNum() == 1) {
            rows = static_cast<uint32_t>(storage.GetDim(0));
            cols = 1;
        }
    }

    tiling.set_rows(rows);
    tiling.set_cols(cols);

    // 预留一定的UB临时空间给Exp等高阶API使用（示例设置为64KB）
    uint32_t tmpSize = 64 * 1024;
    tiling.set_tmpSize(tmpSize);

    // 单核执行
    context->SetBlockDim(1);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

